         if (ccline.cmdlen && firstc != NUL && (some_key_typed || histype == HIST_SEARCH))
         {
             add_to_history(histype, ccline.cmdbuff, TRUE, histype == HIST_SEARCH ? firstc : NUL);
             if (firstc == ':')
